"use client";

import { useRef, useState } from "react";
import Link from "next/link";
import { ArrowDownLeft, ArrowLeftRight, ArrowRight, ArrowUpRight, Archive, ArchiveRestore, Building2, Download, Pencil, Plus, RefreshCw, Search, Smartphone, Target, Trash2, Wallet, Scissors, CalendarClock, ChartNoAxesCombined, Bitcoin, House, Car, CreditCard, HandCoins, Boxes } from "lucide-react";
import { Dialog, DialogContent, DialogDescription, DialogTitle } from "@/components/ui/dialog";
import { FinanceShell } from "./finance-shell";
import { useRouter } from "next/navigation";
import { categories, decimalAmount, parseAmount, validDate } from "@/lib/preview";
import { accountBalance, accountKindLabels, netWorthSummary, balanceHistory, parseSignedAmount, workspaceSummary, topLevelCategoryBudgets, type AccountTransaction, type FinancialAccount, type Transfer, type WorkspaceCommand } from "@/lib/workspace";
import { type WorkspaceBudget as Budget } from "@/lib/workspace";
import { useWorkspace } from "@/lib/use-workspace";
import { usePlanning } from "@/lib/use-planning";
import { nextOccurrence } from "@/lib/planning";
import { FinancialAccountTools, TransferMatching } from "./finance-account-tools";
import { CoreDialog } from "./finance-core-dialogs";
import { usePreferences } from "@/lib/use-preferences";
import { formatMoney, todayInDhaka, weekStartDate, fiscalStartDate } from "@/lib/presentation";
import styles from "@/app/workspace.module.css";

type View = "Overview" | "Accounts" | "Transactions" | "Budgets";
type Modal = { kind: "account" } | { kind: "rename"; account: FinancialAccount } | { kind: "transaction"; initial: AccountTransaction | null } | { kind: "transfer" } | { kind: "budget"; initial: Budget | null } | { kind: "confirm"; title: string; description: string; action: string; command: WorkspaceCommand };
type Store = ReturnType<typeof useWorkspace>;
const accountKinds = accountKindLabels;
const accountIcons = { bank: Building2, cash: Wallet, mobile: Smartphone, investment: ChartNoAxesCombined, crypto: Bitcoin, property: House, vehicle: Car, credit_card: CreditCard, loan: HandCoins, other_asset: Boxes, other_liability: HandCoins };

function localDate() {
  return todayInDhaka();
}
function monthLabel(month: string) {
  return new Intl.DateTimeFormat("en-BD", { month: "long", year: "numeric" }).format(new Date(Number(month.slice(0, 4)), Number(month.slice(5)) - 1, 1));
}

export function FinanceWorkspace({ initialView = "Overview", initialAccount = "all" }: { initialView?: View; initialAccount?: string }) {
  const router = useRouter();
  const store = useWorkspace();
  const planning = usePlanning();
  const [selected, setSelected] = useState<string[]>([]);
  const [core, setCore] = useState<{ kind: "split" | "bulk" | "plan"; transaction?: AccountTransaction } | null>(null);
  const { preferences, reviewCount } = usePreferences();
  const [view, setView] = useState<View>(initialView);
  const [month, setMonth] = useState(() => localDate().slice(0, 7));
  const [search, setSearch] = useState("");
  const [accountFilter, setAccountFilter] = useState(initialAccount);
  const [typeFilter, setTypeFilter] = useState("all");
  const [modal, setModal] = useState<Modal | null>(null);
  const [message, setMessage] = useState("");
  const [hidden, setHidden] = useState(false);
  const displayMoney = (value: number) => hidden ? "••••" : formatMoney(value, preferences.locale);
  const [allHistory, setAllHistory] = useState(false);
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [tagFilter, setTagFilter] = useState("all");
  const [merchantFilter, setMerchantFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [range, setRange] = useState("30D");
  const opener = useRef<HTMLElement | null>(null);
  const today = localDate();
  const data = store.data;
  const summary = workspaceSummary(data, month, today);
  const activeAccounts = data.accounts.filter(account => !account.archived);
  const canChange = store.status === "ready" && !store.pending && !store.stale && !store.uncertain && !planning.pending && !planning.uncertain;
  const canExport = canChange;
  const accountArchived = (id: string | null) => data.accounts.find(account => account.id === id)?.archived ?? false;
  const accountName = (id: string | null) => id === null ? "Unassigned" : data.accounts.find(account => account.id === id)?.name ?? "Unknown account";
  const open = (next: Modal, element?: HTMLElement | null) => { opener.current = element ?? document.activeElement as HTMLElement; setModal(next); };
  const close = () => setModal(null);
  const restoreFocus = () => { if (opener.current?.isConnected) opener.current.focus(); else document.getElementById("workspace-main")?.focus(); };
  const done = (text: string) => { setMessage(text); close(); setCore(null); setSelected([]); void planning.reload(); };
  const openCore = (next: NonNullable<typeof core>, element?: HTMLElement) => { opener.current = element ?? document.activeElement as HTMLElement; setCore(next); };
  const coreDone = (text: string) => { done(text); void store.reload(); };
  const syncLocation = (next: View, account?: string) => { const url = new URL(window.location.href); if(next === "Overview") url.searchParams.delete("view");else url.searchParams.set("view", next.toLowerCase());if(account)url.searchParams.set("account",account);else url.searchParams.delete("account");window.history.replaceState(window.history.state, "", url); };
  const navigate = (next: View) => { setSelected([]); setView(next); setSearch(""); setAccountFilter("all"); setTypeFilter("all");setCategoryFilter("all");setTagFilter("all");setMerchantFilter("all");setStatusFilter("all");syncLocation(next); };
  const inspectAccount = (id: string) => { setSelected([]); setView("Transactions"); setAccountFilter(id); setSearch(""); setTypeFilter("all");setCategoryFilter("all");setTagFilter("all");setMerchantFilter("all");setStatusFilter("all");syncLocation("Transactions",id); };
  const rangeStart = range === "All" ? data.accounts.map(a => a.openingDate).sort()[0] ?? today : range === "WTD" ? weekStartDate(today, preferences.weekStart) : range === "FYTD" ? fiscalStartDate(today, preferences.fiscalYearStartMonth) : range === "YTD" ? `${today.slice(0, 4)}-01-01` : new Date(Date.parse(`${today}T12:00:00Z`) - (range === "90D" ? 89 : 29) * 86400000).toISOString().slice(0, 10);
  const history = balanceHistory(data, rangeStart, today);
  const postedExpenses = data.transactions.filter(t => t.type === "expense" && t.status === "confirmed" && !t.excluded && t.date.startsWith(month) && t.date <= today);
  const outflows = Array.from(postedExpenses.reduce((groups, t) => groups.set(t.category, (groups.get(t.category) ?? 0) + t.poisha), new Map<string, number>())).sort((a,b) => b[1]-a[1]);
  const {assetsPoisha,liabilitiesPoisha:debtsPoisha} = netWorthSummary(data,today);
  const balanceMagnitude = data.accounts.reduce((sum, account) => sum + Math.abs(accountBalance(data, account.id, today)), 0);
  const monthTransactions = data.transactions.filter(transaction => allHistory || transaction.date.startsWith(month));
  const monthTransfers = data.transfers.filter(transfer => allHistory || (transfer.date.startsWith(month) || transfer.toDate.startsWith(month)));
  type Row = { kind: "transaction"; value: AccountTransaction } | { kind: "transfer"; value: Transfer };
  const allRows: Row[] = [...monthTransactions.map(value => ({ kind: "transaction" as const, value })), ...monthTransfers.map(value => ({ kind: "transfer" as const, value }))].sort((a, b) => b.value.date.localeCompare(a.value.date) || b.value.id.localeCompare(a.value.id));
  const rows = allRows.filter(row => {
    const entry = row.value;
    const matchesType = typeFilter === "all" || (row.kind === "transfer" ? typeFilter === "transfer" : row.value.type === typeFilter);
    const matchesAccount = accountFilter === "all" || (row.kind === "transfer" ? row.value.fromAccountId === accountFilter || row.value.toAccountId === accountFilter : accountFilter === "unassigned" ? row.value.accountId === null : row.value.accountId === accountFilter);
    const text = row.kind === "transfer" ? `${entry.description} transfer ${accountName(row.value.fromAccountId)} ${accountName(row.value.toAccountId)}` : `${entry.description} ${row.value.category} ${accountName(row.value.accountId)}`;
    const matchesClassification = row.kind === "transaction" ? (categoryFilter === "all" || row.value.categoryId === categoryFilter) && (tagFilter === "all" || row.value.tagIds.includes(tagFilter)) && (merchantFilter === "all" || row.value.merchantId === merchantFilter) && (statusFilter === "all" || (statusFilter === "excluded" ? row.value.excluded : row.value.status === statusFilter)) : categoryFilter === "all" && tagFilter === "all" && merchantFilter === "all" && statusFilter === "all";
    return matchesType && matchesAccount && matchesClassification && `${text} ${row.kind === "transaction" ? row.value.notes : ""}`.toLowerCase().includes(search.trim().toLowerCase());
  });
  const filteredTotals = rows.reduce((totals,row) => {if(row.kind === "transfer"){if(row.value.date <= today)totals.transfers += row.value.poisha;}else if(row.value.status === "confirmed" && !row.value.excluded && row.value.date <= today){totals[row.value.type] += row.value.poisha;}return totals;}, {income:0,expense:0,transfers:0});
  const hasFilters = !!search || accountFilter !== "all" || typeFilter !== "all" || categoryFilter !== "all" || tagFilter !== "all" || merchantFilter !== "all" || statusFilter !== "all";
  const selectedIds = selected;
  const selectableIds = rows.filter((row): row is Extract<Row, { kind: "transaction" }> => row.kind === "transaction" && !accountArchived(row.value.accountId)).map(row => row.value.id);
  const monthlyPlan = planning.data.monthlyPlans.find(plan => plan.month === month);
  const topLevelBudgets = topLevelCategoryBudgets(data, summary.budgets);
  const allocatedPoisha = topLevelBudgets.reduce((total, budget) => total + BigInt(budget.limitPoisha), 0n);
  const previousMonth = new Date(Date.UTC(Number(month.slice(0, 4)), Number(month.slice(5, 7)) - 2, 1)).toISOString().slice(0, 7);
  const upcoming = planning.data.recurring.map(schedule => ({ schedule, date: nextOccurrence(schedule, schedule.startDate, planning.data.occurrences.filter(occurrence => occurrence.scheduleId === schedule.id).map(occurrence => occurrence.date)) })).filter(item => item.date !== null).sort((a, b) => a.date!.localeCompare(b.date!)).slice(0, 3);
  const toggleSelected = (id: string) => setSelected(previous => previous.includes(id) ? previous.filter(saved => saved !== id) : previous.length < 100 ? [...previous, id] : previous);


  function exportData() {
    if (!canExport) { setMessage("Resolve the previous save or reload saved data before exporting."); return; }
    try {
      const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: "application/json" }));
      const anchor = document.createElement("a");
      anchor.href = url; anchor.download = `budget-go-financial-v4-${today}.json`; anchor.click();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      setMessage("Workspace export download started. Keep this readable financial file private. For a restorable full backup, use Settings → Backups.");
    } catch { setMessage("Export could not start. Your saved data has not changed."); }
  }

  const renderRows = (compact = false) => {
    const list = compact ? allRows.slice(0, 5) : rows;
    return list.length ? list.map((row, index) => {
      const entry = row.value;
      const transfer = row.kind === "transfer";
      const splitGroup = row.kind === "transaction" ? planning.data.splits.find(group => group.partIds.includes(row.value.id)) : undefined;
      const type = row.kind === "transaction" ? row.value.type : "transfer";
      const Icon = transfer ? ArrowLeftRight : type === "income" ? ArrowDownLeft : ArrowUpRight;
      const description = row.kind === "transaction" ? `${row.value.category} · ${accountName(row.value.accountId)}` : `${accountName(row.value.fromAccountId)} → ${accountName(row.value.toAccountId)}`;
      return <div key={`${row.kind}-${entry.id}`}>{!compact && (index === 0 || list[index - 1].value.date !== entry.date) && <h3 className={styles.dateGroup}>{new Intl.DateTimeFormat(preferences.locale, {weekday:"long",day:"numeric",month:"long",year:"numeric",timeZone:"UTC"}).format(new Date(`${entry.date}T00:00:00Z`))}</h3>}<div className={styles.transaction} data-entry-type={type}>{!compact && row.kind === "transaction" && <label className={styles.selectEntry}><input type="checkbox" checked={selectedIds.includes(entry.id)} disabled={!canChange || accountArchived(row.value.accountId) || !selectedIds.includes(entry.id) && selectedIds.length >= 100} onChange={() => toggleSelected(entry.id)} aria-label={`Select ${entry.description}`}/><span className={styles.srOnly}>Select {entry.description}</span></label>}<span className={styles.tile}><Icon size={18} aria-hidden="true" /></span><div className={styles.transactionName}><strong>{entry.description}</strong><p>{description}{splitGroup && <span className={styles.pill}>Split · {splitGroup.partIds.length} parts</span>}{row.kind === "transaction" && accountArchived(row.value.accountId) && " · Restore account to edit"}</p><p><time dateTime={entry.date}>{entry.date}</time>{row.kind === "transfer" && row.value.toDate !== entry.date && <> → <time dateTime={row.value.toDate}>{row.value.toDate}</time></>}{entry.date > today && " · Scheduled"}{row.kind === "transaction" && ` · ${row.value.status === "pending" ? "Pending" : "Confirmed"}${row.value.excluded ? " · Excluded" : ""}`}{row.kind === "transaction" && row.value.merchantId && ` · ${data.merchants.find(m => m.id === row.value.merchantId)?.name ?? ""}`}{row.kind === "transaction" && row.value.tagIds.map(id => <span className={styles.pill} key={id}>{data.tags.find(tag => tag.id === id)?.name}</span>)}</p></div><div className={`${styles.transactionAmount} ${type === "income" ? styles.positive : ""}`}>{transfer ? "" : type === "income" ? "+" : "−"}{displayMoney(entry.poisha)}<span>{transfer ? "Transfer" : type === "income" ? "Income" : "Expense"}</span></div>{!compact && <div className={styles.rowActions}>{row.kind === "transaction" && <button className={styles.iconButton} disabled={!canChange || !row.value.accountId || accountArchived(row.value.accountId) || !!splitGroup} aria-label={`Split ${entry.description}`} onClick={event => openCore({ kind: "split", transaction: row.value }, event.currentTarget)}><Scissors size={17} aria-hidden="true"/></button>}{row.kind === "transaction" && <button className={styles.iconButton} disabled={!canChange || accountArchived(row.value.accountId)} aria-label={`Edit ${entry.description}`} onClick={event => open({ kind: "transaction", initial: row.value }, event.currentTarget)}><Pencil size={17} aria-hidden="true" /></button>}<button className={styles.iconButton} disabled={!canChange || row.kind === "transfer" && data.matches.some(match => match.transferId === row.value.id)} title={row.kind === "transfer" && data.matches.some(match => match.transferId === row.value.id) ? "Unmatch in the matching audit to restore original entries" : undefined} aria-label={`Delete ${entry.description}`} onClick={event => open({ kind: "confirm", title: transfer ? "Delete transfer?" : "Delete transaction?", description: transfer ? `Delete “${entry.description}” for ${displayMoney(entry.poisha)}? Both account balance effects will be removed together.` : `Delete “${entry.description}” for ${displayMoney(entry.poisha)}? This changes the account balance and category spending.`, action: transfer ? "Delete transfer" : "Delete transaction", command: { type: transfer ? "transfer_delete" : "transaction_delete", id: entry.id } }, event.currentTarget)}><Trash2 size={17} aria-hidden="true" /></button></div>}</div></div>;
    }) : <div className={styles.empty}><Search size={26} aria-hidden="true" /><h3>{hasFilters && !compact ? "No matching entries" : "No entries this month"}</h3><p>{hasFilters && !compact ? "Try another account, type or search term." : `Income, expenses and transfers for ${monthLabel(month)} will appear here.`}</p>{hasFilters && !compact ? <button className={styles.quiet} onClick={() => { setSearch(""); setAccountFilter("all"); setTypeFilter("all"); setCategoryFilter("all"); setTagFilter("all"); setMerchantFilter("all"); setStatusFilter("all"); }}>Reset filters</button> : activeAccounts.length > 0 && <button className={styles.secondary} disabled={!canChange} onClick={event => open({ kind: "transaction", initial: null }, event.currentTarget)}>Add transaction</button>}</div>;
  };

  const renderBudgets = (compact = false) => {
    const list = compact ? summary.budgets.slice(0, 3) : summary.budgets;
    return list.length ? <div className={styles.budgetList}>{list.map(budget => {
      const ratio = budget.spentPoisha / budget.limitPoisha;
      return <div className={styles.budgetRow} key={budget.id}><div className={styles.budgetTop}><strong>{budget.category}</strong><span className={ratio > 1 ? styles.negative : ratio >= .8 ? styles.warning : styles.muted}>{budget.status}</span></div><div className={styles.progress} role="progressbar" aria-label={`${budget.category} budget`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.min(100, Math.round(ratio * 100))} aria-valuetext={`${displayMoney(budget.spentPoisha)} spent of ${displayMoney(budget.limitPoisha)}. ${budget.status}`}><span className={ratio > 1 ? styles.over : undefined} style={{ width: `${Math.min(100, ratio * 100)}%` }} /></div><div className={styles.budgetAmounts}><span><strong>{displayMoney(budget.spentPoisha)}</strong> of {displayMoney(budget.limitPoisha)}</span><span>{ratio > 1 ? `${displayMoney(budget.spentPoisha - budget.limitPoisha)} over` : `${displayMoney(budget.limitPoisha - budget.spentPoisha)} left`}</span></div>{!compact && <div className={styles.budgetActions}><button className={styles.iconButton} disabled={!canChange} aria-label={`Edit ${budget.category} budget`} onClick={event => open({ kind: "budget", initial: budget }, event.currentTarget)}><Pencil size={17} aria-hidden="true" /></button><button className={styles.iconButton} disabled={!canChange} aria-label={`Remove ${budget.category} budget`} onClick={event => open({ kind: "confirm", title: "Remove budget?", description: `Remove the ${budget.category} limit for ${monthLabel(month)}? Transactions and account balances will stay as they are.`, action: "Remove budget", command: { type: "budget_delete", id: budget.id } }, event.currentTarget)}><Trash2 size={17} aria-hidden="true" /></button></div>}</div>;
    })}</div> : <div className={styles.empty}><Target size={26} aria-hidden="true" /><h3>Give your month a plan</h3><p>Set category limits and see what is left to spend.</p><button className={styles.secondary} disabled={!canChange} onClick={event => open({ kind: "budget", initial: null }, event.currentTarget)}>Set budget</button></div>;
  };

  return <FinanceShell active={view === "Overview" || view === "Accounts" ? "Home" : view} data={data} onNavigate={next => { if (next === "Reports") router.push("/reports"); else navigate(next === "Home" ? "Overview" : next as View); }} onAccount={inspectAccount} onAddAccount={() => open({kind:"account"})} hidden={hidden} onPrivacy={() => setHidden(value => !value)}><div className={styles.root}>
      <main id="workspace-main" tabIndex={-1} className={styles.main}><div className={styles.pageHeading}><div><p className={styles.eyebrow}>{view === "Overview" ? "YOUR MONEY, IN FOCUS" : "PERSONAL FINANCE"}</p><h1>{view === "Overview" ? "Home" : view}</h1><p>{view === "Overview" ? "Your accounts, cash flow and monthly plan." : view === "Accounts" ? "Keep track of the money in each place." : view === "Transactions" ? "Income, expenses and transfers across your accounts." : `Plan your spending for ${monthLabel(month)}.`}</p></div><div className={styles.headingActions}><label className={styles.srOnly} htmlFor="workspace-month">Month</label><input id="workspace-month" className={styles.month} type="month" min="1000-01" max="9999-12" value={month} onChange={event => { if (/^\d{4}-(0[1-9]|1[0-2])$/.test(event.target.value) && Number(event.target.value.slice(0, 4)) >= 1000) setMonth(event.target.value); }} />{view === "Accounts" ? <button className={styles.button} disabled={!canChange} onClick={event => open({ kind: "account" }, event.currentTarget)}><Plus size={18} aria-hidden="true" />Add account</button> : view === "Budgets" ? <button className={styles.button} disabled={!canChange} onClick={event => open({ kind: "budget", initial: null }, event.currentTarget)}><Plus size={18} aria-hidden="true" />Set budget</button> : <button className={styles.button} disabled={!canChange || !activeAccounts.length} onClick={event => open({ kind: "transaction", initial: null }, event.currentTarget)}><Plus size={18} aria-hidden="true" />Add transaction</button>}</div></div>

      {store.error && <div className={styles.error} role="alert"><p>{store.error}</p>{store.status === "unauthenticated" ? <Link href="/login">Sign in again</Link> : store.uncertain ? <button className={styles.secondary} disabled={store.pending} onClick={() => { void store.retryPending().then(error => { if (!error) setMessage("Previous save confirmed. Your workspace is up to date."); }); }}>Retry previous save safely</button> : <button className={styles.secondary} disabled={store.pending} onClick={() => void store.reload()}><RefreshCw size={16} aria-hidden="true" />Reload saved data</button>}</div>}
      {store.status === "loading" ? <div className={styles.loading} role="status">Loading your workspace…</div> : store.status === "ready" && <>
      {summary.unassignedCount > 0 && <div className={styles.legacyNotice}><div><strong>{summary.unassignedCount} unassigned {summary.unassignedCount === 1 ? "entry" : "entries"}</strong><p>Existing entries are included in cash flow and budgets, but not account balances. Edit each entry to choose its account.</p></div><button className={styles.quiet} onClick={() => { setView("Transactions");syncLocation("Transactions","unassigned"); setAccountFilter("unassigned"); setSearch(""); setTypeFilter("all"); const latest = data.transactions.filter(entry => entry.accountId === null).sort((a, b) => b.date.localeCompare(a.date))[0]; if (latest) setMonth(latest.date.slice(0, 7)); }}>Review entries <ArrowRight size={16} aria-hidden="true" /></button></div>}
      {data.accounts.length === 0 && <div className={styles.notice}><Wallet size={23} aria-hidden="true" /><div><strong>Start with a real account</strong><p>Add a bank account, cash or mobile wallet and its opening balance. Nothing is filled in for you.</p></div><button className={styles.quiet} disabled={!canChange} onClick={event => open({ kind: "account" }, event.currentTarget)}>Add your first account <ArrowRight size={16} aria-hidden="true" /></button></div>}

      {view === "Overview" && <>{reviewCount > 0 && <div className={styles.automationStrip}><span><strong>{reviewCount} alerts waiting for review.</strong> Existing alerts stay separate from your ledger.</span><Link href="/inbox">Review alerts<ArrowRight size={17}/></Link></div>}<section className={styles.upcomingStrip}><div><CalendarClock size={21}/><div><strong>Regular bills &amp; income</strong><p>{planning.status === "ready" ? upcoming.length ? upcoming.map(item => `${item.schedule.name} · ${item.date}`).join("  /  ") : "Plan rent, subscriptions, salary and other regular entries." : "Loading your upcoming schedules…"}</p></div></div><Link href="/recurring">View recurring<ArrowRight size={17}/></Link></section><section className={styles.wealthPanel} aria-labelledby="balance-heading"><div className={styles.wealthTop}><div><h2 id="balance-heading" className={styles.wealthLabel}>Net worth</h2><p className={styles.wealthValue}>{displayMoney(summary.balancePoisha)}</p><p className={styles.wealthMeta}>Assets {displayMoney(assetsPoisha)} · Liabilities {displayMoney(debtsPoisha)}</p><p className={styles.wealthMeta}>Posted position · As of {today} · {data.accounts.length} manual {data.accounts.length === 1 ? "account" : "accounts"}</p></div><button className={styles.quiet} onClick={() => navigate("Accounts")}>View accounts <ArrowRight size={16} aria-hidden="true" /></button></div><div className={styles.rangeTabs} aria-label="Balance history range">{["WTD", "30D", "90D", "YTD", "FYTD", "All"].map(value => <button key={value} aria-pressed={range === value} onClick={() => setRange(value)}>{value}</button>)}</div>{hidden ? <p className={styles.emptyInline}>Balance history hidden. Use Show amounts to reveal it.</p> : data.accounts.length ? <BalanceChart points={history} locale={preferences.locale} /> : <p className={styles.emptyInline}>Your balance history will appear after you add an account.</p>}<div className={styles.wealthFooter}><span>Manual BDT positions include openings, entries and dated valuations.</span><span>Valuations are neutral to income and spending.</span></div></section><div className={styles.cashFlow}><div><span className={styles.tile}><ArrowDownLeft size={18} aria-hidden="true" /></span><div><p>Income · {monthLabel(month)}</p><strong className={styles.positive}>{displayMoney(summary.incomePoisha)}</strong></div></div><div><span className={styles.tile}><ArrowUpRight size={18} aria-hidden="true" /></span><div><p>Expenses · {monthLabel(month)}</p><strong>{displayMoney(summary.expensePoisha)}</strong></div></div><div><span className={styles.tile}><Wallet size={18} aria-hidden="true" /></span><div><p>Net cash flow</p><strong className={summary.incomePoisha >= summary.expensePoisha ? styles.positive : styles.negative}>{displayMoney(summary.incomePoisha - summary.expensePoisha)}</strong></div></div></div><div className={styles.lowerGrid}><section className={styles.panel}><div className={styles.panelHeading}><div><h2>Recent entries</h2><p>{monthLabel(month)} · includes scheduled entries</p></div><button className={styles.quiet} onClick={() => navigate("Transactions")}>View all <ArrowRight size={16} aria-hidden="true" /></button></div>{renderRows(true)}</section><section className={styles.panel}><div className={styles.panelHeading}><div><h2>Monthly budget</h2><p>Expenses posted through {today}</p></div><button className={styles.iconButton} aria-label="View budgets" onClick={() => navigate("Budgets")}><ArrowUpRight size={18} aria-hidden="true" /></button></div>{renderBudgets(true)}</section></div></>}

      {view === "Overview" && <div className={styles.dashboardGrid}><details open className={styles.widget}><summary>Balance sheet <span>Manual BDT positions · {today}</span></summary>{data.accounts.length ? data.accounts.map(account => {const balance = accountBalance(data, account.id, today);return <div className={styles.sheetRow} key={account.id}><span>{account.name}{account.archived ? " · Archived" : ""}</span><strong data-amount>{displayMoney(balance)}</strong><span className={styles.shareBar} aria-label={`${balanceMagnitude ? (Math.abs(balance)/balanceMagnitude*100).toFixed(1) : "0"}% of absolute account balances`}><i style={{width:`${balanceMagnitude ? Math.abs(balance)/balanceMagnitude*100 : 0}%`}}/></span></div>;}) : <p className={styles.emptyInline}>Add an account to see its balance and share here.</p>}<p className={styles.panelFoot}>Account share uses absolute posted balances. All account families, including archived positions. No live prices or currency conversion.</p></details><details open className={styles.widget}><summary>Outflows <span>{monthLabel(month)} · posted expenses</span></summary>{outflows.length ? outflows.map(([category, amount]) => <div className={styles.sheetRow} key={category}><span>{category}</span><strong data-amount>{displayMoney(amount)}</strong><span className={styles.shareBar}><i style={{width:`${summary.expensePoisha ? amount/summary.expensePoisha*100 : 0}%`}}/></span></div>) : <p className={styles.emptyInline}>No posted expenses in this month.</p>}<p className={styles.panelFoot}>Pending, excluded and future entries are omitted.</p></details></div>}

      {view === "Accounts" && <><div className={styles.accountSummary}><section><p>Net worth</p><strong>{displayMoney(summary.balancePoisha)}</strong><small>As of {today}, including archived accounts</small></section><section><p>Active accounts</p><strong>{activeAccounts.length}</strong><small>Cash, investments, assets and debts</small></section><section><p>Archived accounts</p><strong>{data.accounts.length - activeAccounts.length}</strong><small>History and balances are retained</small></section></div><section className={styles.panel}><div className={styles.panelHeading}><div><h2>Your accounts</h2><p>Manual balances · BDT</p></div><button className={styles.secondary} disabled={!canChange || activeAccounts.length < 2} onClick={event => open({ kind: "transfer" }, event.currentTarget)}><ArrowLeftRight size={17} aria-hidden="true" />Transfer</button></div>{data.accounts.length ? data.accounts.map(account => { const Icon = accountIcons[account.kind]; return <div className={styles.accountRow} data-account-kind={account.kind} key={account.id}><span className={styles.tile}><Icon size={20} aria-hidden="true" /></span><div className={styles.accountInfo}><strong>{account.name}{account.archived && <span className={styles.pill}>Archived</span>}</strong><p>{accountKinds[account.kind]} · Opened {account.openingDate}</p><p>Opening balance {displayMoney(account.openingPoisha)}</p></div><div className={styles.accountBalance}>{displayMoney(accountBalance(data, account.id, today))}<span>As of {today}</span></div><div className={styles.accountRowActions}><button className={styles.quiet} onClick={() => inspectAccount(account.id)}>Entries <ArrowRight size={15} aria-hidden="true" /></button><button className={styles.iconButton} disabled={!canChange} aria-label={`Rename ${account.name}`} onClick={event => open({ kind: "rename", account }, event.currentTarget)}><Pencil size={17} aria-hidden="true" /></button><button className={styles.iconButton} disabled={!canChange} aria-label={`${account.archived ? "Restore" : "Archive"} ${account.name}`} onClick={event => open({ kind: "confirm", title: account.archived ? "Restore account?" : "Archive account?", description: account.archived ? `Restore ${account.name} to record new entries again?` : `Archive ${account.name}? Existing entries and balances stay visible. New entries and transfers are blocked until you restore it.`, action: account.archived ? "Restore account" : "Archive account", command: { type: "account_archive", id: account.id, archived: !account.archived } }, event.currentTarget)}>{account.archived ? <ArchiveRestore size={18} aria-hidden="true" /> : <Archive size={18} aria-hidden="true" />}</button></div></div>; }) : <div className={styles.empty}><Wallet size={28} aria-hidden="true" /><h3>No accounts yet</h3><p>Add the places where you keep your money to start tracking balances.</p><button className={styles.button} disabled={!canChange} onClick={event => open({ kind: "account" }, event.currentTarget)}>Add account</button></div>}</section></>}

      {view === "Transactions" && <section className={styles.panel}><div className={styles.filters}><div className={styles.search}><Search size={18} aria-hidden="true" /><label className={styles.srOnly} htmlFor="entry-search">Search entries</label><input id="entry-search" placeholder="Search entries…" value={search} onChange={event => setSearch(event.target.value)} /></div><div className={styles.filter}><label htmlFor="account-filter">Account</label><select id="account-filter" value={accountFilter} onChange={event => {setAccountFilter(event.target.value);syncLocation("Transactions", event.target.value === "all" ? undefined : event.target.value);}}><option value="all">All accounts</option><option value="unassigned">Unassigned</option>{data.accounts.map(account => <option value={account.id} key={account.id}>{account.name}{account.archived ? " (archived)" : ""}</option>)}</select></div><div className={styles.filter}><label htmlFor="type-filter">Entry type</label><select id="type-filter" value={typeFilter} onChange={event => setTypeFilter(event.target.value)}><option value="all">All types</option><option value="income">Income</option><option value="expense">Expenses</option><option value="transfer">Transfers</option></select></div><button className={styles.secondary} disabled={!canChange || activeAccounts.length < 2} onClick={event => open({ kind: "transfer" }, event.currentTarget)}><ArrowLeftRight size={17} aria-hidden="true" />Transfer</button></div><div className={styles.filters}><label className={styles.historyToggle}><input type="checkbox" checked={allHistory} onChange={event => setAllHistory(event.target.checked)}/> All history</label>{([{label:"Category",value:categoryFilter,set:setCategoryFilter,items:data.categories},{label:"Tag",value:tagFilter,set:setTagFilter,items:data.tags},{label:"Merchant",value:merchantFilter,set:setMerchantFilter,items:data.merchants}]).map(filter => <div className={styles.filter} key={filter.label}><label htmlFor={`filter-${filter.label}`}>{filter.label}</label><select id={`filter-${filter.label}`} value={filter.value} onChange={event => filter.set(event.target.value)}><option value="all">All {filter.label.toLowerCase()}s</option>{filter.items.map(item => <option key={item.id} value={item.id}>{item.name}{item.archived ? " (archived)" : ""}</option>)}</select></div>)}<div className={styles.filter}><label htmlFor="status-filter">Status</label><select id="status-filter" value={statusFilter} onChange={event => setStatusFilter(event.target.value)}><option value="all">All statuses</option><option value="confirmed">Confirmed</option><option value="pending">Pending</option><option value="excluded">Excluded</option></select></div></div><div className={styles.selectionBar}><label><input type="checkbox" aria-label="Select visible transactions" checked={selectableIds.length > 0 && selectableIds.every(id => selectedIds.includes(id))} disabled={!canChange || !selectableIds.length} onChange={event => { if (event.target.checked) setSelected(selectableIds.slice(0, 100)); else setSelected([]); }}/><span>Select visible transactions</span></label><span>{selectedIds.length} selected · maximum 100</span>{selectedIds.length > 0 && <><button className={styles.secondary} disabled={!canChange} onClick={event => openCore({kind:"bulk"}, event.currentTarget)}>Edit selected</button><button className={styles.danger} disabled={!canChange} onClick={event => open({kind:"confirm",title:"Delete selected transactions?",description:`Delete ${selectedIds.length} selected transactions? Their account balance and spending effects will be removed together. This cannot be undone.`,action:"Delete selected",command:{type:"transaction_bulk_delete",ids:selectedIds}},event.currentTarget)}>Delete selected</button><button className={styles.quiet} onClick={() => setSelected([])}>Clear selection</button></>}</div><div className={styles.resultCount}><span role="status">{rows.length} of {allRows.length} entries</span><span className={styles.filteredTotals}>Posted income <strong>{displayMoney(filteredTotals.income)}</strong> · Expenses <strong>{displayMoney(filteredTotals.expense)}</strong> · Transfers <strong>{displayMoney(filteredTotals.transfers)}</strong></span>{hasFilters && <button className={styles.quiet} onClick={() => { setSearch(""); setAccountFilter("all"); setTypeFilter("all"); setCategoryFilter("all"); setTagFilter("all"); setMerchantFilter("all"); setStatusFilter("all"); }}>Reset filters</button>}</div>{renderRows()}<div className={styles.panelFoot}>Future-dated entries are marked Scheduled and excluded from today’s balances and spending.</div></section>}

      {view === "Accounts" && <FinancialAccountTools store={store} money={displayMoney} disabled={!canChange} saved={done}/>}
      {view === "Transactions" && <TransferMatching store={store} money={displayMoney} disabled={!canChange} saved={done}/>}
      {view === "Budgets" && <><section className={styles.monthPlan} aria-label="Monthly budget plan"><div className={styles.monthPlanHeading}><div><h2>Your monthly plan</h2><p>Set targets, allocate categories and compare with posted activity.</p></div><div><button className={styles.secondary} disabled={!canChange || planning.status !== "ready"} onClick={event => openCore({kind:"plan"}, event.currentTarget)}>{monthlyPlan ? "Edit monthly targets" : "Set monthly targets"}</button><button className={styles.secondary} disabled={!canChange || summary.budgets.length > 0 || !data.budgets.some(budget => budget.month === previousMonth) || Number(previousMonth.slice(0,4)) < 1000} onClick={event => open({kind:"confirm",title:"Copy previous month’s budgets?",description:`Copy category limits from ${previousMonth} into ${month}? Only limits are copied; targets and actual transactions stay unchanged. The selected month must have no category budgets.`,action:"Copy category budgets",command:{type:"budget_copy",fromMonth:previousMonth,toMonth:month}},event.currentTarget)}>Copy previous month</button></div></div>{planning.error && <div className={styles.error} role="alert"><p>{planning.error}</p><button className={styles.secondary} onClick={() => void planning.reload()}>Reload planning data</button></div>}<div className={styles.planMetrics}><div><span>Expected income</span><strong data-amount>{monthlyPlan ? displayMoney(monthlyPlan.incomePoisha) : "Not set"}</strong><small>Actual {displayMoney(summary.incomePoisha)}</small></div><div><span>Planned spending</span><strong data-amount>{monthlyPlan ? displayMoney(monthlyPlan.spendingPoisha) : "Not set"}</strong><small>Actual {displayMoney(summary.expensePoisha)}</small></div><div><span>Category allocation</span><strong data-amount>{hidden ? "••••" : formatMoney(allocatedPoisha,preferences.locale)}</strong><small>Parent limits include child allocations</small></div><div><span>{monthlyPlan && BigInt(monthlyPlan.spendingPoisha) < allocatedPoisha ? "Overallocated" : "Still to allocate"}</span><strong data-amount>{monthlyPlan ? hidden ? "••••" : formatMoney(BigInt(monthlyPlan.spendingPoisha)-allocatedPoisha,preferences.locale) : "Set a spending target"}</strong><small>{monthlyPlan ? `Target surplus ${displayMoney(monthlyPlan.incomePoisha-monthlyPlan.spendingPoisha)}` : "Targets do not create ledger entries"}</small></div></div><p className={styles.formHelp}>Copying needs an empty destination month and does not overwrite limits. <Link href="/docs/budgets">Budget guide</Link></p></section><section className={styles.panel}><div className={styles.panelHeading}><div><h2>Category budgets</h2><p>{monthLabel(month)} · expenses posted through {today}</p></div></div>{renderBudgets()}<div className={styles.panelFoot}>Transfers and opening balances do not count as spending. Removing a limit keeps all entries.</div></section></>}
      </>}
      <footer className={styles.footer}><button className={styles.quiet} disabled={!canExport} onClick={exportData}><Download size={16}/>Export workspace</button><span>Budget Go · Your private financial workspace</span><span>{monthLabel(month)} · BDT · Manual accounts</span></footer><p className={styles.liveMessage} role="status" aria-live="polite">{message}</p></main>
    {core && <CoreDialog key={core.kind} mode={core.kind} transaction={core.transaction} store={store} planning={planning} month={month} selected={selectedIds} locale={preferences.locale} close={() => setCore(null)} restoreFocus={restoreFocus} done={coreDone}/> }
    {modal && <WorkspaceDialog key={modal.kind === "transaction" || modal.kind === "budget" ? `${modal.kind}-${modal.initial?.id ?? "new"}` : modal.kind} modal={modal} store={store} defaultStatus={preferences.defaultEntryStatus} month={month} today={today} close={close} restoreFocus={restoreFocus} done={done} />}
  </div></FinanceShell>;
}

function BalanceChart({ points, locale }: { points: { date: string; poisha: number }[]; locale: "en-BD" | "bn-BD" }) {
  if (points.length < 2) return <p className={styles.emptyInline}>No balance history in this range yet.</p>;
  const low = Math.min(...points.map(point => point.poisha));
  const high = Math.max(...points.map(point => point.poisha));
  const spread = Math.max(high - low, 100);
  const start = Date.parse(`${points[0].date}T00:00:00Z`);
  const duration = Date.parse(`${points[points.length - 1].date}T00:00:00Z`) - start;
  const path = points.map(point => `${(Date.parse(`${point.date}T00:00:00Z`) - start) * 900 / duration},${170 - (point.poisha - low + spread * .15) / (spread * 1.3) * 160}`);
  return <div data-amount className={styles.chart}><svg viewBox="0 0 900 190" preserveAspectRatio="none" role="img" aria-label={`Account balance history from ${points[0].date} to ${points[points.length - 1].date}, from ${formatMoney(points[0].poisha, locale)} to ${formatMoney(points[points.length - 1].poisha, locale)}. Exact dated values below.`}>{[25, 95, 165].map(y => <line key={y} x1="0" x2="900" y1={y} y2={y} stroke="#303030" strokeDasharray="3 5" />)}<path d={`M${path.join(" L")}`} fill="none" stroke="#8bddb0" strokeWidth="2.5" vectorEffect="non-scaling-stroke" strokeLinejoin="round" /></svg><div className={styles.chartLabels}><span>{points[0].date}</span><span>{points[points.length - 1].date}</span></div><details className={styles.chartDetails}><summary>View dated balance values</summary><ol>{points.map(point => <li key={point.date}>{point.date}: {formatMoney(point.poisha, locale)}</li>)}</ol></details></div>;
}

function WorkspaceDialog({ modal, store, defaultStatus, month, today, close, restoreFocus, done }: { modal: Modal; store: Store; defaultStatus: "confirmed" | "pending"; month: string; today: string; close: () => void; restoreFocus: () => void; done: (message: string) => void }) {
  const active = store.data.accounts.filter(account => !account.archived);
  const initial = modal.kind === "transaction" ? modal.initial : null;
  const budget = modal.kind === "budget" ? modal.initial : null;
  const [form, setForm] = useState<Record<string, string>>({
    notes: initial?.notes ?? "", merchantId: initial?.merchantId ?? "", status: initial?.status ?? defaultStatus, excluded: initial?.excluded ? "yes" : "no",
    name: modal.kind === "rename" ? modal.account.name : "", kind: "bank", openingDate: today, opening: "0.00",
    description: initial?.description ?? "", amount: initial ? decimalAmount(initial.poisha) : budget ? decimalAmount(budget.limitPoisha) : "",
    date: initial?.date ?? (today.startsWith(month) ? today : `${month}-01`),
    type: initial?.type ?? "expense", category: initial?.category ?? budget?.category ?? store.data.categories.find(c => !c.archived && (c.kind === "expense" || c.kind === "both") && (modal.kind !== "budget" || !store.data.budgets.some(b => b.month === month && b.categoryId === c.id)))?.name ?? (modal.kind === "budget" ? categories.expense.find(category => !store.data.budgets.some(b => b.month === month && b.category === category)) : undefined) ?? categories.expense[0],
    accountId: initial?.accountId ?? active[0]?.id ?? "", fromAccountId: active[0]?.id ?? "", toAccountId: active[1]?.id ?? "",
  });
  const [tagIds, setTagIds] = useState<string[]>(initial?.tagIds ?? []);
  const catalogOptions = (kind: "income" | "expense") => store.data.categories.filter(c => (!c.archived || c.name === form.category) && (c.kind === kind || c.kind === "both"));
  const categoryOptions = (kind: "income" | "expense") => catalogOptions(kind).length ? catalogOptions(kind).map(c => c.name) : categories[kind];
  const [error, setError] = useState("");
  const [invalid, setInvalid] = useState<string | null>(null);
  const formRef = useRef<HTMLFormElement>(null);
  const locked = store.pending;
  const change = (field: string, value: string) => setForm(current => ({ ...current, [field]: value }));
  const title = modal.kind === "account" ? "Add account" : modal.kind === "rename" ? "Rename account" : modal.kind === "transaction" ? initial ? "Edit transaction" : "Add transaction" : modal.kind === "transfer" ? "Transfer money" : modal.kind === "budget" ? budget ? "Edit budget" : "Set budget" : modal.title;
  const action = modal.kind === "confirm" ? modal.action : modal.kind === "account" ? "Create account" : modal.kind === "rename" ? "Save name" : modal.kind === "transfer" ? "Create transfer" : modal.kind === "budget" ? "Save budget" : initial ? "Save changes" : "Add transaction";
  const description = modal.kind === "account" ? "Use the actual balance on your opening date. Opening balances are not income." : modal.kind === "rename" ? "Rename this account without changing its opening balance or history." : modal.kind === "transaction" ? "Record a real income or expense in BDT. Choose the account it belongs to." : modal.kind === "transfer" ? "Move money between two accounts. Both balance effects are saved together; this is not income or spending." : modal.kind === "budget" ? `Set a category limit for ${monthLabel(month)}. Existing entries stay unchanged.` : modal.description;

  function fail(field: string, message: string) {
    setInvalid(field); setError(message);
    requestAnimationFrame(() => formRef.current?.querySelector<HTMLElement>(`[name="${field}"]`)?.focus());
  }
  async function submit(event: React.FormEvent) {
    event.preventDefault();
    if (locked) return;
    setInvalid(null); setError("");
    let command: WorkspaceCommand;
    if (modal.kind === "confirm") command = modal.command;
    else if (modal.kind === "account") {
      if (!form.name.trim() || form.name.trim().length > 80) return fail("name", "Enter an account name of 1–80 characters.");
      const openingPoisha = parseSignedAmount(form.opening);
      if (openingPoisha === null) return fail("opening", "Enter an exact opening balance with at most two decimal places. Zero or a negative balance is allowed.");
      if (!validDate(form.openingDate)) return fail("openingDate", "Choose a valid opening date.");
      command = { type: "account_create", account: { name: form.name.trim(), kind: form.kind as FinancialAccount["kind"], openingDate: form.openingDate, openingPoisha } };
    } else if (modal.kind === "rename") {
      if (!form.name.trim() || form.name.trim().length > 80) return fail("name", "Enter an account name of 1–80 characters.");
      command = { type: "account_update", id: modal.account.id, account: { name: form.name.trim() } };
    } else if (modal.kind === "budget") {
      const limitPoisha = parseAmount(form.amount);
      if (limitPoisha === null) return fail("amount", "Enter a positive budget limit with at most two decimal places.");
      if (store.data.budgets.some(item => item.id !== budget?.id && item.month === month && item.category === form.category)) return fail("category", "This category already has a budget for the selected month. Edit that budget instead.");
      const input = { month, category: form.category, categoryId: store.data.categories.find(c => c.name === form.category)?.id ?? null, limitPoisha };
      command = budget ? { type: "budget_update", id: budget.id, budget: input } : { type: "budget_create", budget: input };
    } else {
      if (!form.description.trim() || form.description.trim().length > 120) return fail("description", "Enter a description of 1–120 characters.");
      const poisha = parseAmount(form.amount);
      if (poisha === null) return fail("amount", "Enter a positive amount with at most two decimal places.");
      if (!validDate(form.date)) return fail("date", "Choose a valid calendar date.");
      if (modal.kind === "transfer") {
        if (!form.fromAccountId || !form.toAccountId || form.fromAccountId === form.toAccountId) return fail("toAccountId", "Choose two different active accounts.");
        const dates = active.filter(account => [form.fromAccountId, form.toAccountId].includes(account.id)).map(account => account.openingDate);
        if (dates.some(date => form.date < date)) return fail("date", "The transfer cannot be dated before either account's opening date.");
        command = { type: "transfer_create", transfer: { fromAccountId: form.fromAccountId, toAccountId: form.toAccountId, description: form.description.trim(), date: form.date, poisha } };
      } else {
        const account = active.find(item => item.id === form.accountId);
        if (!account) return fail("accountId", "Choose an active account. Restore an archived account before editing its entries.");
        if (form.date < account.openingDate) return fail("date", "The transaction cannot be dated before the account opening date.");
        const transaction = { accountId: form.accountId, description: form.description.trim(), type: form.type as "income" | "expense", category: form.category, categoryId: store.data.categories.find(c => c.name === form.category)?.id ?? null, merchantId: form.merchantId || null, tagIds, notes: form.notes, status: form.status as "confirmed" | "pending", excluded: form.excluded === "yes", date: form.date, poisha };
        command = initial ? { type: "transaction_update", id: initial.id, transaction } : { type: "transaction_create", transaction };
      }
    }
    const result = await store.save(command);
    if (result) setError(result);
    else done(modal.kind === "confirm" ? `${modal.action} completed.` : modal.kind === "account" ? "Account created." : modal.kind === "transfer" ? "Transfer saved. Both account balances are updated." : modal.kind === "budget" ? "Budget saved." : modal.kind === "rename" ? "Account renamed." : "Transaction saved.");
  }

  function field(name: string, label: string, options: { type?: string; hint?: string; maxLength?: number; inputMode?: "decimal" } = {}) {
    return <div className={styles.field}><label htmlFor={`workspace-${name}`}>{label}</label><input id={`workspace-${name}`} name={name} type={options.type ?? "text"} inputMode={options.inputMode} value={form[name]} onChange={event => change(name, event.target.value)} maxLength={options.maxLength} min={options.type === "date" ? "1000-01-01" : undefined} max={options.type === "date" ? "9999-12-31" : undefined} aria-invalid={invalid === name} aria-describedby={invalid === name ? "workspace-form-error" : options.hint ? `workspace-${name}-hint` : undefined} />{options.hint && <small id={`workspace-${name}-hint`}>{options.hint}</small>}</div>;
  }
  function accountSelect(name: string, label: string) {
    return <div className={styles.field}><label htmlFor={`workspace-${name}`}>{label}</label><select id={`workspace-${name}`} name={name} value={form[name]} onChange={event => change(name, event.target.value)} aria-invalid={invalid === name} aria-describedby={invalid === name ? "workspace-form-error" : undefined}><option value="">Choose account</option>{active.map(account => <option value={account.id} key={account.id}>{account.name}</option>)}</select></div>;
  }

  return <Dialog open onOpenChange={value => { if (!value && !locked) close(); }}><DialogContent className={styles.dialog} onPointerDownOutside={event => event.preventDefault()} onEscapeKeyDown={event => { if (locked) event.preventDefault(); }} onCloseAutoFocus={event => { event.preventDefault(); restoreFocus(); }}><DialogTitle>{title}</DialogTitle><DialogDescription className={styles.dialogDescription}>{description}</DialogDescription><form className={styles.form} ref={formRef} onSubmit={submit} noValidate aria-busy={locked}><fieldset className={styles.fields} disabled={locked || store.uncertain}>
    {(modal.kind === "account" || modal.kind === "rename") && field("name", "Account name", { maxLength: 80 })}
    {modal.kind === "account" && <><div className={styles.field}><label htmlFor="workspace-kind">Account type</label><select id="workspace-kind" name="kind" value={form.kind} onChange={event => change("kind", event.target.value)}>{Object.entries(accountKinds).map(([value,label]) => <option key={value} value={value}>{label}</option>)}</select></div>{field("openingDate", "Opening date", { type: "date" })}{field("opening", "Opening balance (BDT)", { inputMode: "decimal", hint: "Negative means money owed; positive includes overpaid debt. Manual BDT only. Type, opening balance and date are fixed." })}</>}
    {(modal.kind === "transaction" || modal.kind === "transfer") && <>{field("description", "Description", { maxLength: 120 })}{field("amount", "Amount (BDT)", { inputMode: "decimal" })}{modal.kind === "transaction" ? <><div className={styles.pair}><div className={styles.field}><label htmlFor="workspace-type">Transaction type</label><select id="workspace-type" name="type" value={form.type} onChange={event => setForm(current => ({ ...current, type: event.target.value, category: categoryOptions(event.target.value as "income" | "expense")[0] }))}><option value="expense">Expense</option><option value="income">Income</option></select></div><div className={styles.field}><label htmlFor="workspace-category">Category</label><select id="workspace-category" name="category" value={form.category} onChange={event => change("category", event.target.value)}>{categoryOptions(form.type as "income" | "expense").map(category => <option key={category}>{category}</option>)}</select></div></div>{accountSelect("accountId", "Account")}{initial?.accountId === null && <p className={styles.formHelp}>Choosing an account assigns this existing entry. Ensure the opening date is on or before the entry date.</p>}</> : <div className={styles.pair}>{accountSelect("fromAccountId", "From account")}{accountSelect("toAccountId", "To account")}</div>}{field("date", "Date", { type: "date", hint: "Future-dated entries are scheduled and do not affect today's balances." })}</>}
    {modal.kind === "transaction" && <><div className={styles.pair}><div className={styles.field}><label htmlFor="workspace-merchant">Merchant</label><select id="workspace-merchant" value={form.merchantId} onChange={event => change("merchantId", event.target.value)}><option value="">No merchant</option>{store.data.merchants.filter(m => !m.archived || m.id === form.merchantId).map(m => <option key={m.id} value={m.id}>{m.name}{m.archived ? " (archived)" : ""}</option>)}</select></div><div className={styles.field}><label htmlFor="workspace-status">Status</label><select id="workspace-status" value={form.status} onChange={event => change("status", event.target.value)}><option value="confirmed">Confirmed</option><option value="pending">Pending</option></select><small>Pending entries do not affect posted balances or spending.</small></div></div><div className={styles.field}><span>Tags</span><div className={styles.tagChoices}>{store.data.tags.filter(tag => !tag.archived || tagIds.includes(tag.id)).map(tag => <label key={tag.id}><input type="checkbox" checked={tagIds.includes(tag.id)} onChange={event => setTagIds(current => event.target.checked ? [...current, tag.id] : current.filter(id => id !== tag.id))}/><span style={{borderColor:tag.color}}>{tag.name}</span></label>)}{!store.data.tags.length && <small>Create tags in Settings → Tags.</small>}</div></div><div className={styles.field}><label htmlFor="workspace-notes">Notes</label><textarea id="workspace-notes" name="notes" maxLength={2000} rows={3} value={form.notes} onChange={event => change("notes", event.target.value)}/></div><label className={styles.historyToggle}><input type="checkbox" checked={form.excluded === "yes"} onChange={event => change("excluded", event.target.checked ? "yes" : "no")}/> Exclude from cash flow, budgets and reports</label><p className={styles.formHelp}>A confirmed excluded entry still changes the account balance. Transfers are recorded separately.</p></>}
    {modal.kind === "budget" && <><div className={styles.field}><label htmlFor="workspace-category">Expense category</label><select id="workspace-category" name="category" value={form.category} onChange={event => change("category", event.target.value)} aria-invalid={invalid === "category"}>{categoryOptions("expense").map(category => <option key={category}>{category}</option>)}</select></div>{field("amount", "Monthly limit (BDT)", { inputMode: "decimal" })}</>}
    </fieldset>{(error || store.uncertain || store.stale) && <div className={styles.formError} role="alert" id="workspace-form-error"><p>{error || store.error} Your draft is still here.</p>{store.uncertain ? <button className={styles.secondary} type="button" disabled={locked} onClick={() => { void store.retryPending().then(result => { if (result) setError(result); else done("Previous save confirmed. Your workspace is up to date."); }); }}>Retry same save safely</button> : <button className={styles.quiet} type="button" disabled={locked} onClick={() => void store.reload()}>Reload saved data</button>}</div>}<div className={styles.formActions}><button className={styles.secondary} type="button" disabled={locked} onClick={close}>Cancel</button><button className={modal.kind === "confirm" && modal.command.type.includes("delete") ? styles.danger : styles.button} type="submit" disabled={locked || store.uncertain || store.stale}>{locked ? "Saving…" : action}</button></div></form></DialogContent></Dialog>;
}
